      for (int j = i + 1; j < arr.size(); ++j)
        for (int k = j + 1; k < arr.size(); ++k)
          if (abs(arr[i] - arr[j]) <= a &&  //
              abs(arr[j] - arr[k]) <= b &&  //
              abs(arr[i] - arr[k]) <= c)
            ++ans;
    return ans;
  }
};

