    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n; ++j) {
        if (i == j)
          continue;
        grid[i][j] == 1 ? ++inDegrees[j] : ++inDegrees[i];
      }

    for (int i = 0; i < n; ++i)
